const OMOJI_TECHNIQUE_SCHEME = Object.freeze({"skyTop":"#161732","skyHorizon":"#51446b","fog":"#515473","glow":"#d8c1fb","ambient":"#bacce6","earth":"#36504d","foliage":"#3c5558","mountain":"#536080","rock":"#666782","road":"#606477","shoulder":"#677187","density":0.002,"seed":6211,"sun":[-0.48,0.18,-0.87],"slope":0,"gradeWaves":[0,0],"stars":1,"clouds":0.55,"snow":false,"biome":"meadow","horizontal":0.23,"forestDensity":0.13});

function omojiTechniqueWrap(distance, length) {
    return (distance % length + length) % length;
}

function omojiTechniqueWorld(track) {
    const step = 4;
    const count = track.length / step;
    const half = count / 2;
    const entries = [];
    const easeTurn = (d, from, to) => d > from && d < to
        ? 2 * Math.sin(Math.PI * (d - from) / (to - from)) ** 2 / (to - from) : 0;
    // The second half mirrors the first, keeping the road closed at the seam.
    const curveAt = d => Math.PI * easeTurn(d, 396, 1052)
        - .34 * easeTurn(d, 216, 420) + .34 * easeTurn(d, 1032, 1220);
    let x = 0, z = 0, heading = 0;
    for (let i = 0; i < half; i++) {
        const d = i * step;
        entries.push({d, x, z, heading, grade: 0, curve: curveAt(d), y: 0});
        const turn = curveAt(d + step / 2) * step;
        x += Math.sin(heading + turn / 2) * step;
        z -= Math.cos(heading + turn / 2) * step;
        heading += turn;
    }
    for (let i = 0; i < half; i++) {
        const point = entries[i];
        entries.push({...point, d: point.d + track.length / 2,
            x: x - point.x, z: z - point.z, heading: point.heading + Math.PI});
    }
    entries.push({...entries[0], d: track.length, heading: 2 * Math.PI});

    function sample(distance, target = {}) {
        const position = omojiTechniqueWrap(distance, track.length) / step;
        const start = Math.floor(position);
        const lower = entries[start], upper = entries[start + 1], ratio = position - start;
        target.x = lt(lower.x, upper.x, ratio);
        target.y = 0;
        target.z = lt(lower.z, upper.z, ratio);
        target.heading = lt(lower.heading, upper.heading, ratio);
        target.curve = lt(lower.curve, upper.curve, ratio);
        target.grade = 0;
        return target;
    }

    function nearest(worldX, worldZ) {
        const distanceSquared = point => (point.x - worldX) ** 2 + (point.z - worldZ) ** 2;
        let bestIndex = 0, bestDistance = Infinity;
        const spacing = 12;
        for (let i = 0; i < count; i += spacing) {
            const distance = distanceSquared(entries[i]);
            if (distance < bestDistance) {
                bestDistance = distance;
                bestIndex = i;
            }
        }
        let bestOffset = bestIndex * step;
        for (let offset = -spacing; offset <= spacing; offset++) {
            const point = entries[(bestIndex + offset + count) % count];
            const next = entries[point.d / step + 1];
            const dx = next.x - point.x, dz = next.z - point.z;
            const fraction = Re(((worldX - point.x) * dx + (worldZ - point.z) * dz) / (dx * dx + dz * dz), 0, 1);
            const distance = distanceSquared({x: point.x + dx * fraction, z: point.z + dz * fraction});
            if (distance < bestDistance) {
                bestDistance = distance;
                bestOffset = point.d + step * fraction;
            }
        }
        return {point: sample(bestOffset, {d: bestOffset}), distance: Math.sqrt(bestDistance)};
    }
    return {track, scheme: OMOJI_TECHNIQUE_SCHEME, length: track.length, width: track.width, sample, nearest, entries,
        gripAt: () => track.grip};
}

function omojiCreateTechnique(raceId) {
    return {id: raceId || globalThis.crypto?.randomUUID?.() || ('technique-' + Date.now() + '-' + Math.random().toString(36).slice(2)),
        clock: 0, position: 0, bestPosition: 0, paid: 0, bank: 0, sequence: 0, nextPayAt: 3.8,
        recoveryUntil: 0, move: '', moveUntil: 0, error: false, ended: false, ticket: null, pending: null};
}

function omojiPayTechnique(state, ending = false) {
    if (!state) return;
    state.ended ||= ending;
    if (state.pending) return;
    if (!state.ticket) {
        const amount = Math.min(2000, Math.floor(state.bank));
        if (amount < (state.ended ? 1 : 42)) return;
        state.ticket = {sequence: state.sequence + 1, amount};
        state.bank -= amount;
    }
    const {sequence, amount} = state.ticket;
    state.nextPayAt = state.clock + 3.8;
    state.pending = Promise.resolve().then(() => omojiAwardTechniqueZ(state.id, sequence, amount)).then(paid => {
        state.sequence = sequence;
        state.ticket = null;
        state.paid += Number.isFinite(paid) ? Math.max(0, paid) : 0;
        state.error = false;
    }, () => { state.error = true; }).finally(() => {
        state.pending = null;
        if (state.ended && !state.error) omojiPayTechnique(state);
    });
}

function omojiTechniqueStep(game, before, dt) {
    const state = game.omojiTechnique, car = game.player, length = game.world.length;
    state.clock += dt;
    const advance = car.distance - before;
    state.position += advance;
    const newGround = Re(state.position - state.bestPosition, 0, Math.max(0, advance));
    state.bestPosition = Math.max(state.bestPosition, state.position);
    if (car.distance >= length || car.distance < 0) car.distance = omojiTechniqueWrap(car.distance, length);
    const wallClearance = oh(car.stats, game.world) - Math.abs(car.offset);
    if (car.wallSide || car.impact >= .12) state.recoveryUntil = state.clock + .9;
    const aligned = Math.abs(_i(car.heading - car.slipAngle)) < .53;
    if (newGround > .004 && car.speed > 12 && aligned && wallClearance > .8 && state.clock >= state.recoveryUntil) {
        const slip = Math.abs(car.slipAngle), speedKmh = car.speed * 3.6;
        const curvature = Math.abs(game.trackPoint.curve || 0);
        const lateralG = curvature * car.speed ** 2 / 9.81;
        let points = 0, move = '';
        if (slip > .11 && slip < .53) {
            points = Re(34 + (slip - .11) * 120 + car.speed * .72, 34, 100);
            move = 'ドリフト';
        } else if (lateralG > .24 && slip < .11 && Math.abs(car.offset) < game.world.width * .32) {
            points = Re(22 + lateralG * 55, 25, 70) * (game.assist ? .72 : 1);
            move = 'コーナリング';
        } else if (speedKmh >= 105 && curvature < .0033) {
            points = Re(22 + (speedKmh - 105) * .34, 22, 64);
            move = '高速走行';
        }
        if (points) {
            state.bank += points * dt * Re(newGround / advance, 0, 1);
            state.move = move;
            state.moveUntil = state.clock + .9;
        }
    }
    if (state.clock >= state.nextPayAt) omojiPayTechnique(state);
}

function omojiTechniqueSetup(track) {
    const active = !!track.endlessTechnique;
    Y('mode-list').hidden = active;
    Y('mode-list').previousElementSibling.hidden = active;
    if (!active) return;
    Y('difficulty-field').hidden = true;
    Y('launch-track').textContent = track.name + ' · 1周 ' + track.lengthKm + ' km';
    Y('launch-car').textContent = Ht(ye.car).name + ' · テクニック走行';
    Y('launch-xp').hidden = false;
    Y('launch-xp').textContent = '走行中に技を決めてZ獲得 · ソロ専用';
}

function omojiTechniqueHud(snapshot) {
    const state = snapshot.technique;
    const active = !!state;
    for (const element of [Cn['race-time'], Cn['race-best'], Cn['race-progress'].parentElement]) {
        if (element.hidden !== active) element.hidden = active;
    }
    if (!active) return;
    zn('race-position', '+' + Rt(state.paid));
    const context = state.error ? 'Zの保存を再試行中' : state.clock < state.moveUntil ? state.move : 'この走行の獲得Z';
    zn('race-context', context);
}



function omojiCourseBonus(track) {
    if (!track.bonusStage || track.endurance) return track;
    const kilometers = track.length / 1000;
    const routeDemand = track.wet || track.snow ? 1.09 : 1;
    const technical = track.tier === "上級" ? 1.10 : track.tier === "初級" ? .94 : 1;
    const variety = Math.round(Math.min(450, Math.max(0, (track.bonusReward ?? 6500) - 6500) * .015));
    const amount = Math.round(((580 + kilometers * 1530) * routeDemand * technical + variety) / 50) * 50;
    return Object.freeze({...track, bonusReward: Math.round(amount * 1.4 / 50) * 50 * 6});
}


