function omojiGuardrailSection(side) {
    const profile = [
        [-.40,-.51], [-.48,-.45], [-.43,-.30], [.08,-.265], [.36,-.18],
        [.17,-.071], [-.36,-.033], [-.36,.035], [.16,.075], [.36,.175],
        [.08,.272], [-.43,.316], [-.48,.455], [-.40,.51],
    ];
    const points = [], faces = [], colors = [];
    for (let band = 0; band < profile.length - 1; band++) {
        const [ax, ay] = profile[band], [bx, by] = profile[band + 1];
        const shade = .78 + (.42 + ax + bx) * .12 + (band % 2) * .065;
        const base = points.length / 3;
        points.push(ax * side, ay, -.5, bx * side, by, -.5, ax * side, ay, .5, bx * side, by, .5);
        for (let i = 0; i < 4; i++) colors.push(shade, shade * .986, shade * .955);
        faces.push(...(side > 0 ? [base,base+2,base+1,base+1,base+2,base+3] : [base,base+1,base+2,base+1,base+3,base+2]));
    }
    const geometry = new He();
    geometry.setAttribute('position', new Te(points, 3));
    geometry.setAttribute('color', new Te(colors, 3));
    geometry.setIndex(faces);
    geometry.computeVertexNormals();
    return geometry;
}

function omojiHighRails(scene, sections, posts, scheme, sectors) {
    if (!sections.length) return;
    const steel = new js({color:scheme.snow ? '#aeb9bc' : '#939c9e', shininess:49, specular:'#858789', vertexColors:true, side:tn});
    steel.name = 'OMOJI Corrugated Galvanized Guardrail';
    for (const side of [-1, 1]) {
        const beams = sections.filter(section => section.side === side);
        rt(scene, omojiGuardrailSection(-side), steel, beams, sectors);
    }
    const fittings = [];
    for (const post of posts) {
        if (!post.fittings) continue;
        const fastening = {at:post.fittings, angle:post.angle, size:[.044,.16,.18]};
        fittings.push(fastening);
    }
    const mount = new js({color:'#7b8487',specular:'#a8afb1',shininess:32});
    mount.name = 'OMOJI Barrier Fasteners';
    rt(scene, new nt(), mount, fittings, sectors);
}
