        const y = heightAt + Math.abs(side) * (broad ? 8 : 15) + dt(n + 9.7) * 9;
        const radius = (3 + dt(n + .61) * (broad ? 11 : 8)) * (broad ? 1 : .70 + .6 * branch);
        const light = Math.max(0, .42 - side * .4 + dt(n + .78) * .32);
