    const span = outer - inner;
    const lower = inner + span * (.06 + .14 * variation);
    const upper = lower + span * (.18 + variation * .12);
    const endLower = lower + span * (dt(from.d * .23 + side + 3) - .5) * .28;
    const endUpper = endLower + span * (.2 + variation * .1);
    const groundFrom = (lane) => gr(-.04, fromElevation, (lane - inner) / span) + .025;
    const groundTo = (lane) => gr(-.04, toElevation, (lane - inner) / span) + .025;
    brush.globalAlpha = Math.max(0, 1 - distance / 110) * (.12 + variation * .30);
