function omojiRaceCarZone(vehicle, forward, lateral, length, width) {
    const angle = vehicle.heading;
    const localForward = Math.cos(angle) * forward + Math.sin(angle) * lateral;
    const localRight = Math.cos(angle) * lateral - Math.sin(angle) * forward;
    if (Math.abs(localForward) / length >= Math.abs(localRight) / width) return localForward >= 0 ? "front" : "rear";
    return localRight >= 0 ? "right" : "left";
}

