    const otherPath = opponent.heading - opponent.slipAngle;
    const velocityForward = player.speed * Math.cos(playerPath) - opponent.speed * Math.cos(otherPath);
    const velocitySide = player.speed * Math.sin(playerPath) - opponent.speed * Math.sin(otherPath);
