const OMOJI_TURBINE_MAX = 24;
const OMOJI_TURBINE_SPEED_STEP = 20;
const OMOJI_TURBINE_ACCEL_STEP = 30;

function omojiTurbineLevel(carId) {
    return Xi(Mi().cars[carId]?.turbineLevel, OMOJI_TURBINE_MAX);
}

function omojiTurbinePrice(currentLevel) {
    const level = Xi(currentLevel, OMOJI_TURBINE_MAX);
    return level < OMOJI_TURBINE_MAX ? 1000 + 600 * level + 210 * level * level : 0;
}

async function omojiBuyTurbine(carId, expectedLevel, expectedPrice) {
    if (typeof carId !== "string") return {status:"unavailable"};
    return Oo(() => {
        const car = Ht(carId);
        if (!car || !_r(car) || Pt.open) return {status:"unavailable"};
        const setup = fa(carId);
        const level = Xi(setup.turbineLevel, OMOJI_TURBINE_MAX);
        const price = omojiTurbinePrice(level);
        const balance = We.balance;
        if (!price) return {status:"max",level,balance};
        if (expectedLevel !== level || expectedPrice !== price) return {status:"changed",level,price,balance};
        if (balance < price) return {status:"funds",level,price,balance};
        const previous = We.cars[carId];
        try {
            if (lp || !globalThis.localStorage) return {status:"error",level,price,balance};
        } catch {
            return {status:"error",level,price,balance};
        }
        We.balance -= price;
        We.cars[carId] = {...setup, turbineLevel:level + 1};
        pa();
        if (lp) {
            We.balance = balance;
            if (previous) We.cars[carId] = previous;
            else delete We.cars[carId];
            pa();
            return {status:"error",level,price,balance};
        }
        return {status:"done",level:level + 1,price,balance:We.balance};
    });
}

const OMOJI_NITRO_LEVEL_MAX = 15;
