    tractionAid:(car.tractionAid ?? 0) + f('tractionAid'),
    aeroGrip:(car.aeroGrip ?? 0) + f('aeroGrip'),
    wetGrip:(car.wetGrip ?? 0) + f('wetGrip'),
    steeringResponse:(car.steeringResponse ?? 1) + f('steeringResponse'),
    steeringRatio:(car.steeringRatio ?? 0) + f('steeringRatio'),
    rollSupport:(car.rollSupport ?? 0) + f('rollSupport'),
