const gpRankPoints = Object.freeze([25,18,15,12,10,8,6,4]);

function gpSafeId(id) {
    return typeof id === 'string' && /^[a-z0-9][a-z0-9_-]{0,79}$/i.test(id);
}

function gpNormalize(progress, event) {
    if (!progress || !event || !gpSafeId(event.id) || progress.eventId !== event.id ||
        !Array.isArray(event.tracks) || event.tracks.length !== 8 ||
        !gpSafeId(progress.carId) || !Array.isArray(progress.bots) || progress.bots.length !== 7 ||
        !Array.isArray(progress.rounds) || progress.rounds.length > event.tracks.length) return null;

    const driverIds = new Set(['player']);
    const bots = [];
    for (const bot of progress.bots) {
        if (!bot || !gpSafeId(bot.id) || !gpSafeId(bot.carId) || driverIds.has(bot.id) ||
            typeof bot.name !== 'string' || bot.name.length > 80 || !bot.name.trim() ||
            /[\u0000-\u001f\u007f]/.test(bot.name)) return null;
        driverIds.add(bot.id);
        bots.push({id: bot.id, name: bot.name.trim(), carId: bot.carId});
    }

    const rounds = [];
    for (const order of progress.rounds) {
        if (!Array.isArray(order) || order.length !== driverIds.size ||
            new Set(order).size !== driverIds.size || !Array.from(order).every(id => driverIds.has(id))) return null;
        rounds.push(order.slice());
    }

    return {eventId: event.id, carId: progress.carId, bots, rounds};
}

function gpNew(event, carId, bots) {
    return gpNormalize({eventId: event?.id, carId, bots, rounds: []}, event);
}

function gpRecord(progress, event, roundIndex, finishingOrder) {
    if (!progress || !event || !Array.isArray(event.tracks) || !Array.isArray(progress.rounds) ||
        roundIndex !== progress.rounds.length || roundIndex >= event.tracks.length) return null;
    return gpNormalize({...progress, rounds: [...progress.rounds, finishingOrder]}, event);
}

function gpStandings(progress) {
    const standings = [{id: 'player', name: null, carId: progress.carId}, ...progress.bots]
        .map(driver => ({...driver, points: 0, places: gpRankPoints.map(() => 0), lastPlace: null}));
    const byId = new Map(standings.map(row => [row.id, row]));
    for (const order of progress.rounds) {
        order.forEach((id, place) => {
            const row = byId.get(id);
            row.points += gpRankPoints[place];
            row.places[place] += 1;
            row.lastPlace = place + 1;
        });
    }
    return standings.sort((a, b) => {
        if (a.points !== b.points) return b.points - a.points;
        for (let place = 0; place < gpRankPoints.length; place++) {
            if (a.places[place] !== b.places[place]) return b.places[place] - a.places[place];
        }
        return (a.lastPlace ?? gpRankPoints.length) - (b.lastPlace ?? gpRankPoints.length);
    });
}

function gpEarned(titles, events) {
    const earned = new Set(Array.isArray(titles) ? titles : []);
    return events.filter(event => earned.has(event.id)).map(event => event.id);
}


