const gpSweepAward = Object.freeze({"id":"grand-sweep","title":"十六冠の王者"});
const gpStorageKey = 'omoji-z.grand-prix.v1';
let gpMemorySave;
let gpStorageFailed = false;
let gpSelectedEvent = '';

function gpFindEvent(id) {
    return gpEventCatalog.find(event => event.id === id);
}

function gpNameValue(value) {
    return typeof value === 'string' ? [...value.replace(/[\p{C}]/gu, '').trim()].slice(0, 16).join('') : '';
}

function gpNewAttempt(event, carId, bots, runId) {
    const progress = gpNew(event, carId, bots);
    return progress && gpSafeId(runId) ? {...progress, runId} : null;
}

function gpSanitizeSave(raw) {
    const attempts = {};
    for (const event of gpEventCatalog) {
        const attempt = raw?.attempts?.[event.id];
        const progress = gpNormalize(attempt, event);
        if (progress && gpSafeId(attempt.runId)) attempts[event.id] = {...progress, runId: attempt.runId};
    }
    const earned = gpEarned(raw?.earned, gpEventCatalog);
    const requested = raw?.displayTitle;
    const displayTitle = earned.includes(requested) ||
        (requested === gpSweepAward.id && earned.length === gpEventCatalog.length) ? requested : '';
    return {attempts, earned, displayTitle, driverName: gpNameValue(raw?.driverName)};
}

function gpActiveTitle(save) {
    if (save.displayTitle === gpSweepAward.id && save.earned.length === gpEventCatalog.length) return gpSweepAward.title;
    return save.earned.includes(save.displayTitle) ? gpFindEvent(save.displayTitle)?.title || '' : '';
}

function gpApplyRound(save, snapshot, order) {
    const event = gpFindEvent(snapshot?.eventId);
    const current = event && save.attempts[event.id];
    if (!current || current.runId !== snapshot.runId) return null;
    const progress = gpRecord(current, event, snapshot.roundIndex, order);
    if (!progress) return null;
    const attempt = {...progress, runId: current.runId};
    const standings = gpStandings(attempt);
    const champion = attempt.rounds.length === event.tracks.length && standings[0].id === 'player';
    const earned = [];
    const state = {...save, attempts: {...save.attempts, [event.id]: attempt}};
    if (champion && !save.earned.includes(event.id)) {
        state.earned = [...save.earned, event.id];
        state.displayTitle = event.id;
        earned.push(event.id);
        if (state.earned.length === gpEventCatalog.length) {
            state.displayTitle = gpSweepAward.id;
            earned.push(gpSweepAward.id);
        }
    }
    return {state, attempt, champion, earned};
}

function gpReadSave() {
    if (!gpStorageFailed) {
        try {
            gpMemorySave = gpSanitizeSave(JSON.parse(globalThis.localStorage.getItem(gpStorageKey)));
        } catch {
            gpMemorySave ??= gpSanitizeSave(null);
        }
    }
    return gpMemorySave ??= gpSanitizeSave(null);
}

function gpWriteSave(save) {
    gpMemorySave = save;
    try {
        globalThis.localStorage.setItem(gpStorageKey, JSON.stringify(save));
        gpStorageFailed = false;
    } catch {
        gpStorageFailed = true;
    }
}

function gpDriver(save) {
    return save.driverName || gpNameValue(E_()) || 'プレイヤー';
}

function gpNode(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
}

function gpButton(label, className, handler) {
    const button = gpNode('button', className, label);
    button.type = 'button';
    button.addEventListener('click', handler);
    return button;
}

function gpPaintBadges(save = gpReadSave(), race = Ct) {
    const title = gpActiveTitle(save);
    const player = gpDriver(save);
    Y('gp-header-title').hidden = !title;
    Y('gp-header-driver').textContent = player;
    Y('gp-header-title-text').textContent = title;
    Y('gp-race-title').textContent = title && race ? player + ' · ' + title : '';
    Y('gp-race-title').hidden = !(title && race);
    const grandPrix = race?.grandPrix;
    Y('gp-race-round').hidden = !grandPrix;
    Y('gp-race-round').textContent = grandPrix ? gpFindEvent(grandPrix.eventId).name +
        ' · 第' + (grandPrix.roundIndex + 1) + '戦 / 8' : '';
}

function gpPaintProfile(save) {
    const name = gpNode('input', '');
    name.type = 'text';
    name.maxLength = 48;
    name.autocomplete = 'nickname';
    name.value = save.driverName;
    name.placeholder = gpDriver(save);
    const nameLabel = gpNode('label', 'gp-title-select', 'プレイヤー名');
    nameLabel.append(name);
    const form = gpNode('form', 'gp-driver-form');
    const saveButton = gpNode('button', 'quiet', '名前を保存');
    saveButton.type = 'submit';
    form.append(nameLabel, saveButton);
    form.addEventListener('submit', event => {
        event.preventDefault();
        const next = {...gpReadSave(), driverName: gpNameValue(name.value)};
        gpWriteSave(next);
        gpPaintBadges(next);
        gpPaintDetail(next, false);
        gpPaintMessage('プレイヤー名を保存しました。');
        name.value = next.driverName;
        name.placeholder = gpDriver(next);
    });
    const slot = Y('gp-titles');
    slot.hidden = false;
    slot.replaceChildren(form);
    if (!save.earned.length) return;
    const select = gpNode('select', '');
    const label = gpNode('label', 'gp-title-select', '表示する称号');
    select.append(new Option('称号を表示しない', ''));
    for (const event of gpEventCatalog) {
        if (save.earned.includes(event.id)) select.append(new Option(event.title, event.id));
    }
    if (save.earned.length === gpEventCatalog.length) select.append(new Option(gpSweepAward.title, gpSweepAward.id));
    select.value = save.displayTitle;
    select.addEventListener('change', () => {
        const next = gpSanitizeSave({...gpReadSave(), displayTitle: select.value});
        gpWriteSave(next);
        gpPaintBadges(next);
        gpPaintDetail(next, false);
        gpPaintMessage('表示する称号を更新しました。');
    });
    label.append(select);
    slot.append(label);
}

function gpPaintMessage(message) {
    Y('gp-status').textContent = message;
}

function gpPaintList(save) {
    const cards = gpEventCatalog.map((event, index) => {
        const attempt = save.attempts[event.id];
        const won = save.earned.includes(event.id);
        const art = gpNode('img', 'gp-card-image');
        art.src = './assets/' + event.cover;
        art.alt = '';
        art.width = 580;
        art.height = 390;
        art.loading = 'lazy';
        art.decoding = 'async';
        art.draggable = false;
        const card = gpButton('', 'gp-card', () => {
            gpSelectedEvent = event.id;
            gpPaintDetail(gpReadSave(), true);
        });
        const text = gpNode('span', 'gp-card-content');
        const marks = [String(index + 1).padStart(2, '0') + ' / 16'];
        if (won) marks.push('制覇済み');
        if (attempt && attempt.rounds.length < 8) marks.push(attempt.rounds.length + ' / 8戦');
        card.toggleAttribute('data-earned', won);
        card.setAttribute('aria-controls', 'gp-detail');
        card.setAttribute('aria-expanded', String(gpSelectedEvent === event.id));
        card.dataset.gpEvent = event.id;
        text.append(gpNode('span', 'gp-card-kicker', marks.join(' · ')), gpNode('strong', '', event.name),
            gpNode('span', '', '称号「' + event.title + '」'));
        card.append(art, text);
        return card;
    });
    Y('gp-list').replaceChildren(...cards);
}

function gpStandingsTable(attempt, save) {
    const tableWrap = gpNode('div', 'gp-table-wrap');
    const table = gpNode('table', 'gp-table');
    const heading = gpNode('thead', '');
    const headers = gpNode('tr', '');
    for (const text of ['総合', 'ドライバー', '前戦', '得点']) {
        const th = gpNode('th', '', text);
        th.scope = 'col';
        headers.append(th);
    }
    heading.append(headers);
    const body = gpNode('tbody', '');
    for (const [index, driver] of gpStandings(attempt).entries()) {
        const self = driver.id === 'player';
        const row = gpNode('tr', self ? 'gp-self' : '');
        const driverCell = gpNode('th', '', '');
        driverCell.scope = 'row';
        driverCell.append(gpNode('bdi', '', self ? gpDriver(save) : driver.name));
        const title = self && gpActiveTitle(save);
        if (title) driverCell.append(gpNode('span', 'gp-driver-title', title));
        if (self) driverCell.append(gpNode('small', 'gp-driver-you', 'あなた'));
        row.append(gpNode('td', '', attempt.rounds.length ? String(index + 1) : '—'), driverCell,
            gpNode('td', '', driver.lastPlace ? String(driver.lastPlace) + '位' : '—'), gpNode('td', '', String(driver.points)));
        body.append(row);
    }
    table.append(heading, body);
    tableWrap.append(table);
    return tableWrap;
}

function gpPaintDetail(save, focus) {
    const panel = Y('gp-detail');
    const event = gpFindEvent(gpSelectedEvent);
    Y('gp-list').querySelectorAll('[data-gp-event]').forEach(button => {
        button.setAttribute('aria-expanded', String(button.dataset.gpEvent === gpSelectedEvent));
    });
    panel.hidden = !event;
    if (!event) return;
    const attempt = save.attempts[event.id];
    const completed = attempt?.rounds.length === event.tracks.length;
    const head = gpNode('header', 'gp-detail-head');
    const title = gpNode('h3', '', event.name);
    title.tabIndex = -1;
    const car = Ht(attempt && !completed ? attempt.carId : ye.car);
    const badge = save.earned.includes(event.id) ? '獲得済みの称号' : '優勝称号';
    head.append(title, gpNode('p', '', event.summary), gpNode('p', 'gp-driver-title', badge + '「' + event.title + '」'),
        gpNode('p', '', '使用車両　' + (car?.name || 'ガレージの選択車両')));
    const rounds = gpNode('ol', 'gp-rounds');
    for (const [index, id] of event.tracks.entries()) {
        const track = ii(id);
        const order = attempt?.rounds[index];
        const row = gpNode('li', '', '');
        row.append(gpNode('span', '', track.name + ' · ' + track.lengthKm + ' km'));
        if (order) {
            const place = order.indexOf('player');
            row.append(gpNode('small', '', (place + 1) + '位 · ' + gpRankPoints[place] + '点'));
        } else if (index === (attempt?.rounds.length ?? 0)) {
            row.setAttribute('aria-current', 'step');
            row.append(gpNode('small', '', '次のレース'));
        }
        rounds.append(row);
    }
    const actions = gpNode('div', 'gp-actions');
    const text = !attempt ? '第1戦を走る' : completed ? 'この大会に再挑戦' : '第' + (attempt.rounds.length + 1) + '戦を走る';
    actions.append(gpButton(text, 'primary', () => gpStartEvent(event)));
    const garageLink = gpNode('a', 'ghost', 'ガレージ');
    garageLink.href = '#garage';
    if (!attempt || completed) actions.append(garageLink);
    const close = gpButton('大会一覧へ', 'quiet', () => {
        gpSelectedEvent = '';
        gpPaintDetail(save, false);
        Y('gp-list').querySelector('[data-gp-event="' + event.id + '"]')?.focus();
    });
    actions.append(close);
    panel.replaceChildren(head, actions, rounds);
    if (attempt?.rounds.length) {
        const label = gpNode('h4', '', completed ? '最終順位' : '総合順位');
        panel.append(label, gpStandingsTable(attempt, save));
    }
    if (focus) {
        title.focus({preventScroll: true});
        panel.scrollIntoView({block: 'start'});
    }
}

function gpRender() {
    const save = gpReadSave();
    gpPaintBadges(save);
    gpPaintProfile(save);
    gpPaintList(save);
    gpPaintDetail(save, false);
    gpPaintMessage(save.earned.length + ' / 16 大会制覇' +
        (save.earned.length === gpEventCatalog.length ? ' · 「' + gpSweepAward.title + '」獲得済み' : ' · 全制覇称号「' + gpSweepAward.title + '」'));
}

function gpPickBots(carId) {
    const used = new Set([carId]);
    const names = ['アキラ', 'ナギ', 'レイ', 'ミナト', 'ヒカリ', 'カエデ', 'ソウ'];
    return names.map((name, index) => {
        const car = ip(used);
        used.add(car.id);
        return {id: 'gp-cpu-' + (index + 1), name, carId: car.id};
    });
}

function gpStartEvent(event) {
    if (Ta || Ve || Pt.open) return;
    if (ri.inRoom()) {
        gpPaintMessage('フリールームから退出するとグランプリに出走できます。');
        return;
    }
    const save = gpReadSave();
    let attempt = save.attempts[event.id];
    if (!attempt || attempt.rounds.length === event.tracks.length) {
        const car = Ht(ye.car);
        if (!car || !_r(car)) {
            gpPaintMessage('出走する車両をガレージで選んでください。');
            return;
        }
        attempt = gpNewAttempt(event, car.id, gpPickBots(car.id), ww());
        if (!attempt) return;
        gpWriteSave({...save, attempts: {...save.attempts, [event.id]: attempt}});
    }
    gpLaunchRound(event, attempt);
}

function gpLaunchRound(event, attempt) {
    const track = ii(event.tracks[attempt.rounds.length]);
    const car = Ht(attempt.carId);
    if (!track || !car || !_r(car)) {
        gpPaintMessage('大会の車両を読み込めませんでした。ガレージの所有車を確認してください。');
        return;
    }
    const roundIndex = attempt.rounds.length;
    G2({id: 'gp-' + attempt.runId + '-' + roundIndex, startedAt: Date.now(),
        car: {...ga(car), paint: wr(car)}, track, mode: 'duel', difficulty: ye.difficulty,
        quality: ye.quality, assist: ye.assist, transmission: ye.transmission,
        grandPrix: {eventId: event.id, roundIndex, runId: attempt.runId, bots: attempt.bots}});
}

function gpClearResult() {
    Y('gp-result').hidden = true;
    Y('gp-result').replaceChildren();
    Y('gp-result-action').hidden = true;
    Y('gp-result-action').removeAttribute('aria-disabled');
    delete Y('gp-result-action').dataset.nextRound;
    Y('retry-race').hidden = false;
    Y('gp-result-return').textContent = 'レース設定に戻る';
}

function gpResultPanel(result) {
    const race = Ct;
    if (!race?.grandPrix) return;
    const snapshot = race.grandPrix;
    const event = gpFindEvent(snapshot.eventId);
    const resultView = Y('gp-result');
    const action = Y('gp-result-action');
    const applied = gpApplyRound(gpReadSave(), snapshot, result.grandPrixOrder);
    if (!applied) {
        resultView.replaceChildren(gpNode('p', '', 'このラウンドの結果は記録済み、または出走記録を読み込めませんでした。大会画面で進行を確認できます。'));
        action.textContent = '大会へ戻る';
    } else {
        gpWriteSave(applied.state);
        const complete = applied.attempt.rounds.length === event.tracks.length;
        const head = complete ? (applied.champion ? '総合優勝' : '大会完走') : '第' + (snapshot.roundIndex + 1) + '戦の結果';
        const place = result.grandPrixOrder.indexOf('player') + 1;
        const parts = [gpNode('h3', '', event.name + ' · ' + head),
            gpNode('p', '', place + '位 · 獲得 ' + gpRankPoints[place - 1] + '点')];
        for (const id of applied.earned) {
            const title = id === gpSweepAward.id ? gpSweepAward.title : gpFindEvent(id).title;
            parts.push(gpNode('p', 'gp-driver-title', '称号獲得「' + title + '」'));
        }
        if (gpStorageFailed) parts.push(gpNode('p', '', 'ブラウザーの保存設定により、この進行はページを開いている間だけ保持します。'));
        parts.push(gpStandingsTable(applied.attempt, applied.state));
        resultView.replaceChildren(...parts);
        action.textContent = complete ? '大会へ戻る' : '第' + (applied.attempt.rounds.length + 1) + '戦へ';
        gpPaintBadges(applied.state, race);
        if (!complete) action.dataset.nextRound = 'yes';
    }
    Y('retry-race').hidden = true;
    Y('gp-result-return').textContent = '大会画面に戻る';
    resultView.hidden = false;
    action.hidden = false;
    action.focus({preventScroll: true});
}

function gpHandleFinish(result) {
    const gpRace = Ct;
    const pending = B2(result);
    if (!gpRace?.grandPrix) return pending;
    const action = Y('gp-result-action');
    delete action.dataset.nextRound;
    gpResultPanel(result);
    action.setAttribute('aria-disabled', 'true');
    void Promise.resolve(pending).finally(() => {
        if (Ct === gpRace) action.removeAttribute('aria-disabled');
    });
    return pending;
}

function gpOnResultAction() {
    const snapshot = Ct?.grandPrix;
    const action = Y('gp-result-action');
    if (!snapshot || Ta || action.hidden || action.getAttribute('aria-disabled') === 'true') return;
    const event = gpFindEvent(snapshot.eventId);
    const attempt = gpReadSave().attempts[event.id];
    if (action.dataset.nextRound === 'yes' && attempt?.runId === snapshot.runId &&
        attempt.rounds.length === snapshot.roundIndex + 1 && attempt.rounds.length < event.tracks.length) {
        gpLaunchRound(event, attempt);
        return;
    }
    Nh();
}

function gpAfterExit(race) {
    if (!race?.grandPrix) return;
    gpSelectedEvent = race.grandPrix.eventId;
    gpRender();
    Pw.go('#grand-prix', {focus: true});
}

function gpInitialize() {
    gpRender();
    Y('gp-result-action').addEventListener('click', gpOnResultAction);
    document.querySelectorAll('a[href="#grand-prix"]').forEach(link => link.addEventListener('click', gpRender));
    window.addEventListener('storage', event => {
        if (event.key === gpStorageKey && !Pt.open && !gpStorageFailed) gpRender();
    });
}

