const omojiMaintenanceParts = new Map([["body",{"action":"板金修理","base":100,"rate":16}],["paint",{"action":"塗装・磨き","base":50,"rate":7}],["lights",{"action":"ガラス・ライト交換","base":75,"rate":11}],["wheels",{"action":"ホイール・足回り整備","base":75,"rate":12}]]);
let omojiWorkshop;

function omojiServicePrice(kind, severity) {
  const part = omojiMaintenanceParts.get(kind);
  if (!part || !Number.isFinite(severity) || severity <= 0) return 0;
  return part.base + part.rate * Math.min(100, Math.max(1, Math.round(severity)));
}

function omojiMountWorkshop(panel) {
  const overview = panel.querySelector("#maintenance-overview");
  const status = panel.querySelector("#maintenance-status");
  const rows = Array.from(panel.querySelectorAll("[data-maintenance]"), row => ({
    kind: row.dataset.maintenance,
    row,
    bar: row.querySelector("progress"),
    wear: row.querySelector("[data-wear-percent]"),
    button: row.querySelector("[data-maintenance-action]"),
    price: row.querySelector("[data-maintenance-price]"),
    quote: 0
  }));
  let car;
  let busy = false;

  function message(text, error = false) {
    status.textContent = text;
    status.dataset.error = String(error);
  }

  function refresh(balance) {
    if (!car) return;
    const damage = omojiRaceGetDamage(car.id);
    let repairCount = 0;
    for (const entry of rows) {
      const severity = damage?.[entry.kind] ?? 0;
      const quote = omojiServicePrice(entry.kind, severity);
      if (quote) repairCount++;
      entry.quote = quote;
      entry.row.dataset.damaged = String(quote > 0);
      entry.bar.value = severity;
      entry.wear.textContent = severity ? "損傷 " + severity + "%" : "損傷なし";
      entry.button.setAttribute("aria-disabled", String(!quote || busy));
      entry.price.textContent = quote
        ? Rt(quote) + (balance < quote ? "・所持Z不足" : "")
        : "整備不要";
    }
    overview.textContent = repairCount ? repairCount + "か所に損傷" : "損傷なし";
    overview.dataset.damaged = String(repairCount > 0);
  }

  for (const entry of rows) {
    entry.button.addEventListener("click", async () => {
      if (!car || busy || !entry.quote) return;
      const currentCar = car;
      const quote = entry.quote;
      const label = omojiMaintenanceParts.get(entry.kind).action;
      busy = true;
      refresh(ig());
      message(label + "を確認中…");
      let result;
      try {
        result = await omojiServiceCar(currentCar.id, entry.kind, quote);
      } catch {
        result = {status: "error"};
      } finally {
        busy = false;
        refresh(ig());
      }
      if (car?.id !== currentCar.id) return;
      switch (result?.status) {
        case "done":
          ss();
          Mr?.refresh();
          message(label + "が完了しました（" + Rt(result.price ?? quote) + "）。");
          break;
        case "clean":
          message("この部位に損傷はありません。");
          break;
        case "price-changed":
          message("損傷に応じて費用が変わりました。新しい金額を確認してください。", true);
          break;
        case "funds":
          message(Rt(result.price ?? quote) + "が必要です。所持Zは" + Rt(result.balance ?? ig()) + "です。", true);
          break;
        case "busy":
          message("別の整備を処理中です。少し待ってからお試しください。", true);
          break;
        case "unavailable":
          message("現在、この車両を整備できません。", true);
          break;
        default:
          message("整備内容を保存できませんでした。もう一度お試しください。", true);
      }
    });
  }
  ug(refresh);

  return nextCar => {
    if (car?.id !== nextCar?.id) message("");
    car = nextCar;
    refresh(ig());
  };
}

function omojiRenderGarageDamage(car) {
  const panel = Y("maintenance-panel");
  if (panel) {
    omojiWorkshop ??= omojiMountWorkshop(panel);
    omojiWorkshop(car);
  }
}

let omojiTurbinePanel;

function omojiMountTurbinePanel(panel) {
    const view = Object.fromEntries(Array.from(panel.querySelectorAll('[data-turbine]'), node => [node.dataset.turbine, node]));
    const signed = number => '+' + qt.format(number);
    let car;
    let busy = false;

    function message(text, error = false) {
        view.status.textContent = text;
        view.status.dataset.error = String(error);
    }

    function render(balance, stats) {
        if (!car) return;
        const level = omojiTurbineLevel(car.id);
        const price = omojiTurbinePrice(level);
        const max = level >= OMOJI_TURBINE_MAX;
        const funds = !max && balance < price;
        const values = stats ?? ga(car);
        view.summary.textContent = 'Lv.' + level + (max ? ' MAX' : ' / ' + OMOJI_TURBINE_MAX);
        view.car.textContent = car.name;
        view.level.textContent = 'Lv.' + level + ' / ' + OMOJI_TURBINE_MAX;
        view.progress.max = OMOJI_TURBINE_MAX;
        view.progress.value = level;
        view.speed.textContent = signed(values.turbineSpeedBonus ?? level * OMOJI_TURBINE_SPEED_STEP) + ' km/h';
        view.acceleration.textContent = signed(values.turbineAccelerationBonus ?? level * OMOJI_TURBINE_ACCEL_STEP) + ' pt';
        view.totalSpeed.textContent = qt.format(values.topSpeed) + ' km/h';
        view.balance.textContent = Rt(balance);
        view.buy.disabled = busy || max || funds;
        view.buy.textContent = max ? 'Lv.' + OMOJI_TURBINE_MAX + ' MAX' : 'Lv.' + (level + 1) + 'に強化 · ' + Rt(price);
        view.quote.textContent = funds ? 'あと ' + Rt(price - balance) + ' 必要です。' : '';
        view.buy.dataset.expectedLevel = String(level);
        view.buy.dataset.expectedPrice = String(price);
    }

    view.buy.addEventListener('click', async () => {
        if (!car || view.buy.disabled || busy) return;
        const target = car;
        const expectedLevel = Number(view.buy.dataset.expectedLevel);
        const expectedPrice = Number(view.buy.dataset.expectedPrice);
        busy = true;
        render(ig());
        message('タービンを強化しています…');
        let result;
        try {
            result = await omojiBuyTurbine(target.id, expectedLevel, expectedPrice);
        } catch {
            result = {status: 'error'};
        } finally {
            busy = false;
            render(ig());
        }
        if (car?.id !== target.id) return;
        if (result.status === 'done') {
            ss(false);
            message('タービンをLv.' + result.level + 'に強化しました。');
        } else if (result.status === 'max') {
            message('タービンは最大レベルです。');
        } else if (result.status === 'changed') {
            message('タービンのレベルが更新されました。新しい費用を確認してください。', true);
        } else if (result.status === 'funds') {
            message('所持Zが不足しています。', true);
        } else if (result.status === 'unavailable') {
            message('この車両のタービンは現在強化できません。', true);
        } else {
            message('タービンを強化できませんでした。もう一度お試しください。', true);
        }
    });

    ug(balance => { if (!Pt.open) render(balance); });
    Pt.addEventListener('close', () => render(ig()));
    return (nextCar, stats) => {
        if (car?.id !== nextCar.id) message('');
        car = nextCar;
        render(ig(), stats);
    };
}

function omojiCompactSpeed(speed) {
    const value = Cn['race-speed'];
    const compact = speed >= 1000;
    if (value.hasAttribute('data-four-digit-speed') !== compact) {
        value.toggleAttribute('data-four-digit-speed', compact);
    }
}

function omojiRenderTurbine(car, stats) {
    const panel = Y('turbine-panel');
    if (!panel) return;
    omojiTurbinePanel ??= omojiMountTurbinePanel(panel);
    omojiTurbinePanel(car, stats);
}

let omojiNitroPanel;

function omojiRenderNitroLevel(car) {
    const panel = Y('nitro-level-panel');
    if (!panel) return;
    omojiNitroPanel ??= omojiMountNitroLevel(panel);
    omojiNitroPanel(car);
}

function omojiMountNitroLevel(panel) {
    const view = Object.fromEntries(Array.from(panel.querySelectorAll('[data-nitro-level]'), node => [node.dataset.nitroLevel, node]));
    let car;
    let busy = false;

    function render(balance) {
        if (!car) return;
        const level = omojiNitroLevel(car.id);
        const price = omojiNitroLevelPrice(level);
        const max = level === OMOJI_NITRO_LEVEL_MAX;
        const extra = level * OMOJI_NITRO_LEVEL_SPEED;
        view.name.textContent = car.name;
        view.summary.textContent = 'Lv.' + level + (max ? ' MAX' : ' / ' + OMOJI_NITRO_LEVEL_MAX);
        view.progress.value = level;
        view.speed.textContent = '+' + qt.format(extra) + ' km/h';
        view.balance.textContent = Rt(balance);
        view.buy.disabled = busy || max || balance < price;
        view.buy.textContent = max ? '最大レベル' : 'Lv.' + (level + 1) + 'に強化 · ' + Rt(price);
        view.buy.dataset.expectedLevel = String(level);
        view.quote.textContent = balance < price ? 'あと ' + Rt(price - balance) + ' 必要です。' : '';
    }

    view.buy.addEventListener('click', async () => {
        if (!car || busy || view.buy.disabled) return;
        const selected = car;
        const level = Number(view.buy.dataset.expectedLevel);
        busy = true;
        view.buy.disabled = true;
        view.status.textContent = 'ニトロを強化しています…';
        let result;
        try {
            result = await omojiBuyNitroLevel(selected.id, level);
        } catch {
            result = {status:'error'};
        } finally {
            busy = false;
            render(ig());
        }
        if (selected.id !== car?.id) return;
        if (result.status === 'done') {
            view.status.textContent = 'ニトロをLv.' + result.level + 'に強化しました。';
            return;
        }
        view.status.textContent = {
            max:'ニトロは最大レベルです。',
            changed:'レベルが更新されました。新しい強化費を確認してください。',
            funds:'所持Zが不足しています。',
            unavailable:'この車両は現在強化できません。',
            error:'強化を保存できませんでした。'
        }[result.status];
    });

    ug(balance => { if (!Pt.open) render(balance); });
    Pt.addEventListener('close', () => render(ig()));
    return nextCar => {
        if (car?.id !== nextCar?.id) view.status.textContent = '';
        car = nextCar;
        render(ig());
    };
}

function omojiNitroLevelHud(state) {
    const badge = Y('race-nitro-level');
    if (!badge) return;
    const bonus = Ct?.car?.nitroLevelSpeedBonus ?? 0;
    const active = state.nitroAvailable && state.nitroActive && bonus > 0;
    badge.hidden = !active;
    if (active) {
        const label = '+' + bonus + ' km/h';
        if (badge.textContent !== label) badge.textContent = label;
    }
}
